INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(48311, 'Zechariah 5:5', 'Zechariah', 5, 5, 'بيا هغه فرښته چې ما سره يې خبرې کولې ما ته نزدې راغله او ما ته يې وفرمائيل، ”بره وګوره او هغه څۀ چې ښکارى دا څۀ دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah5_verse_5.mp3', '', 1761754199, 1761754199),
(48312, 'Zechariah 5:6', 'Zechariah', 5, 6, 'ما ترې تپوس وکړو چې، ”دا څۀ دى؟“ هغې جواب راکړو، ”دا د پېمانې ټوکرۍ ده.“ او هغې دا وفرمائيل چې، ”چې د ټول مُلک د خلقو د بې‌اِنصافۍ نه ډکه ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah5_verse_6.mp3', '', 1761754199, 1761754199),
(48313, 'Zechariah 5:7', 'Zechariah', 5, 7, 'بيا د سيکې دروند سر د ټوکرۍ نه اوچت کړے شو، او په ټوکرۍ کښې يوه ښځه ناسته وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah5_verse_7.mp3', '', 1761754199, 1761754199),
(48314, 'Zechariah 5:8', 'Zechariah', 5, 8, 'فرښتې وفرمائيل، ”د دې ښځې نامه بدعملى ده،“ او هغې هغه په ټوکرۍ کښې بيا ورديکه کړه او د سيکې دروند سر يې پرې کېښودو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah5_verse_8.mp3', '', 1761754199, 1761754199),
(48315, 'Zechariah 5:9', 'Zechariah', 5, 9, 'بيا ما بره وکتل، او زما په وړاندې دوه ښځې وې، چې وزرې يې په هوا کښې وې. د هغوئ وزرې لکه د زاڼې د وزرې په شان وې، او هغوئ دا ټوکرۍ د زمکې نه آسمان ته وخېژوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah5_verse_9.mp3', '', 1761754199, 1761754199),
(48316, 'Zechariah 5:10', 'Zechariah', 5, 10, '”هغوئ دا ټوکرۍ چرته وړى؟“ ما د هغه فرښتې نه چې ما سره يې خبرې کولې تپوس وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah5_verse_10.mp3', '', 1761754199, 1761754199),
(48317, 'Zechariah 5:11', 'Zechariah', 5, 11, 'هغې جواب راکړو چې، ”د بابل مُلک ته چې د هغې دپاره هلته يو کور تيار کړى. کله چې هغه تيار شى، نو هلته به ټوکرۍ په خپل ځائ کېښودے شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah5_verse_11.mp3', '', 1761754199, 1761754199),
(48318, 'Ezra 3:1', 'Ezra', 3, 1, 'کله چې اوومه میاشت راورسېدله، د اسراییلو قوم په خپلو ښارګوټو کې ځای په ځای شول. بیا هغوی ټول په اورشلیم کې په اتفاق سره راټول شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_1.mp3', '', 1761754199, 1761754199),
(48319, 'Ezra 3:2', 'Ezra', 3, 2, 'د یوصاداق زوی یشوع او د هغه ملګرو کاهنانو، د شالتي ییل زوی زروبابل او د هغه خپلوانو د اسراییلو د خدای د قربانۍ ځای بیا جوړ کړ، ترڅو هغوی وکولای شي د هغو حکمونو سره سم چې د خدای د نبي موسی په شریعت کې لیکل شوي وو، سوځېدونکې نذرانې وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_2.mp3', '', 1761754199, 1761754199),
(48320, 'Ezra 3:3', 'Ezra', 3, 3, 'که څه هم راستانه شوي جلاوطني خلک د هغو خلکو څخه چې په هغه خاوره کې اوسېدل وېرېدل، خو هغوی هغه د قربانۍ ځای په خپل پخواني ځای کې بیا جوړ کړ. وروسته یې په هغه باندې څښتن ته د سهارنیو او ماښامنیو سوځېدونکو قربانیو وړاندې کول بیا پیل کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_3.mp3', '', 1761754199, 1761754199),
(48321, 'Ezra 3:4', 'Ezra', 3, 4, 'هغوی د لیکل شویو اصولو سره سم د جونګړو اختر ولمانځه او هره ورځ یې د هماغې ورځې سوځېدونکې قربانۍ وړاندې کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_4.mp3', '', 1761754199, 1761754199),
(48322, 'Ezra 3:5', 'Ezra', 3, 5, 'برسېره پردې، هغوی عادي سوځېدونکې نذرانې، د نوې میاشتې قربانۍ او د څښتن د نورو ټولو ټاکل شویو سپېڅلو جشنونو قربانۍ وړاندې کړې او هغوی هغه نذرانې هم راوړلې چې څښتن ته به په خپله خوښه ورکول کېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_5.mp3', '', 1761754199, 1761754199),
(48323, 'Ezra 3:6', 'Ezra', 3, 6, 'که څه هم خلکو لا د عبادتځای د بیا جوړونې کار نه ؤ پیل کړی، هغوی د اوومې میاشتې په لومړۍ ورځ څښتن ته د سوځېدونکو نذرانو په وړاندې کولو پیل وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_6.mp3', '', 1761754199, 1761754199),
(48324, 'Ezra 3:7', 'Ezra', 3, 7, 'خلکو ګلکارانو او نجارانو ته پیسې ورکړې او همدارنګه یې د صور او صیدون ښارونو ته خواړه، څښاک او د زیتونو تېل ورولېږل چې د هغو په بدل کې د لبنان څخه د سبر ونې د بحیرې له لارې یافا ته راوړل شي. دا کار د فارس د پاچا کوروش په اجازه وشو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_7.mp3', '', 1761754199, 1761754199),
(48325, 'Ezra 3:8', 'Ezra', 3, 8, 'نو د دوهم کال په دوهمه میاشت وروسته له دې چې هغوی بېرته په اورشلیم کې هغه ځای ته راغلل چې مخکې په کې د خدای کور ؤ، په کار یې پیل وکړ. زروبابل، یشوع او د هغوی نور وطنداران، یعنې کاهنان او لاویان او هغه ټول جلاوطني خلک چې بېرته اورشلیم ته راغلي وو، د هغوی سره په کار کې بوخت شول. هغه ټول لاویان چې عمرونه یې شل کاله او یا زیات وو د خدای د کور د بیا جوړونې د کار مسوولان وټاکل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_8.mp3', '', 1761754199, 1761754199),
(48326, 'Ezra 3:9', 'Ezra', 3, 9, 'لاوي یشوع او د هغه زامن او خپلوان او قدمي ییل او د هغه زامن چې د هودویا له طایفې څخه وو، سره یوځای شول چې د خدای د کور د بیا جوړونې مسوولیت په غاړه واخلي. د هغوی سره د حیناداد د طایفې لاویانو مرسته کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_9.mp3', '', 1761754199, 1761754199),
(48327, 'Ezra 3:10', 'Ezra', 3, 10, 'کله چې معمارانو د خدای د کور تهداب کېښود، کاهنانو چې چپنې یې اغوستې وې او په لاسونو کې یې سرني وو او هغه لاویان چې د اساف له طایفې څخه وو، د خپلو شرنګېدونکو زنګونو سره په هغه ځای کې ودرېدل. هغوی د داود د لارښوونې سره سم د څښتن ثنا وویله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_10.mp3', '', 1761754199, 1761754199),
(48328, 'Ezra 3:11', 'Ezra', 3, 11, 'هغوی په خپل وار د ثنا په ویلو او شکرګزارۍ سره څښتن ته دا سندره ویله: ځکه چې نېک دی څښتن د هغه مینه ابدي ده اسراییلو سره هغوی ټولو په لوړ اواز چیغې وهلې او د څښتن ثنا یې ویله، ځکه چې د څښتن د کور بنیاد ایښودل شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_11.mp3', '', 1761754199, 1761754199),
(48329, 'Ezra 3:12', 'Ezra', 3, 12, 'ډېرو زړو کاهنانو، لاویانو او د طایفو مشرانو چې د خدای لومړنی کور یې لیدلی ؤ، نو څنګه چې هغوی ولیدل چې د دې کور تهداب ایښودل پیل شوي دي، هغوی په لوړ اواز ژړا وکړه. خو نورو خلکو له خوشحالۍ چیغې ووهلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_12.mp3', '', 1761754199, 1761754199),
(48330, 'Ezra 3:13', 'Ezra', 3, 13, 'هېچا د خوشحالۍ له چیغو او ژړا ترمنځ فرق نه شو کولای، ځکه چې هغوی داسې شورماشور جوړ کړی ؤ چې د ډېر لېرې ځای څخه اورېدل کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra3_verse_13.mp3', '', 1761754199, 1761754199),
(48331, 'Psalms 60:1', 'Psalms', 60, 1, 'تا مونږه رد کړو خدایه هم دې کړې ماتې د دفاع ځایونه زمونږ ته خفه شوی یې له مونږ اوس مونږه بېرته په خپل حال کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms60_verse_1.mp3', '', 1761754199, 1761754199),
(48332, 'Psalms 60:2', 'Psalms', 60, 2, 'تا ولړزوله ځمکه او هغه دې وشکوله اوس یې بېرته کړه راجوړه ځکه اوس هغه زنګیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms60_verse_2.mp3', '', 1761754199, 1761754199),
(48333, 'Psalms 60:3', 'Psalms', 60, 3, 'تا خپل خلک کړاوونو کې اخته کړل تا راکړل شراب مونږ ته مونږ یې ړنګ او بنګ کړلو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms60_verse_3.mp3', '', 1761754199, 1761754199),
(48334, 'Psalms 60:4', 'Psalms', 60, 4, 'تا اشاره وکړه هغو ته چې عبادت کړي ستا چې د دښمن د غشو وتښتي دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms60_verse_4.mp3', '', 1761754199, 1761754199),
(48335, 'Psalms 60:5', 'Psalms', 60, 5, 'په خپل طاقت دې مونږه وژغوره او قبوله زمونږ دعا کړه ترڅو نجات ومومي هغه خلک د هغه چا سره چې مینه کوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms60_verse_5.mp3', '', 1761754199, 1761754199),
(48336, 'Psalms 60:6', 'Psalms', 60, 6, 'د خپل سپېڅلي ځای نه خدای خبرې وکړې «په خوشحالۍ به زه شکیم تقسیم کړم او د سکوت دره به ووېشم خپل قوم باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms60_verse_6.mp3', '', 1761754199, 1761754199),
(48337, 'Psalms 60:7', 'Psalms', 60, 7, 'جلعاد زما دی او منسي مې هم دی دی افرایم مې د زغرو خولۍ او یهودا مې شاهانه امسا ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms60_verse_7.mp3', '', 1761754199, 1761754199),
(48338, 'Psalms 60:8', 'Psalms', 60, 8, 'خو د موآب نه به کار واخلم د لګن په شان خپلې څپلۍ به د ادوم په لور ګوزارې کړمه په فلسطین باندې به چیغه د بریا وکړمه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms60_verse_8.mp3', '', 1761754199, 1761754199),
(48339, 'Psalms 60:9', 'Psalms', 60, 9, 'څوک به مې بوځي د برجونو ښار ته؟ څوک به مې بوځي د ادوم ښار ته؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms60_verse_9.mp3', '', 1761754199, 1761754199),
(48340, 'Psalms 60:10', 'Psalms', 60, 10, 'تا په رښتیا سره پرې ایښي یو مونږ؟ زمونږ د لښکرو سره نور نه ځې ته؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms60_verse_10.mp3', '', 1761754199, 1761754199),
(48341, 'Psalms 60:11', 'Psalms', 60, 11, 'مرسته مو وکړه د دښمن په خلاف نه لري ګټه د انسان مرسته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms60_verse_11.mp3', '', 1761754199, 1761754199),
(48342, 'Psalms 60:12', 'Psalms', 60, 12, 'مونږ به کامیاب شو چې خدای مل وي زمونږ هغه سرکوب به کړي زمونږ دښمنان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms60_verse_12.mp3', '', 1761754199, 1761754199),
(48343, 'Joshua 9:1', 'Joshua', 9, 1, 'د اسراییلو د بریالیتوبونو څخه هغه ټول پاچاهان خبر شول چې د اردن د سیند په لوېدیځ کې وو، یعنې کوم چې په غرنۍ سیمه، د غرونو په لوېدیځو لمنو او د مدیترانې د بحیرې د غاړې څخه شمال خواته تر لبنان پورې اوسېدل. دا د حیتیانو، اموریانو، کنعانیانو، فرزیانو، حویانو او یبوسیانو پاچاهان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_1.mp3', '', 1761754199, 1761754199),
(48344, 'Joshua 9:2', 'Joshua', 9, 2, 'هغوی ټول سره راټول شول او د یوشع او اسراییلیانو په وړاندې د جنګ دپاره یې خپل قوتونه سره یو کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_2.mp3', '', 1761754199, 1761754199),
(48345, 'Joshua 9:3', 'Joshua', 9, 3, 'خو د جبعون خلکو چې حویان وو، واورېدل چې یوشع په اریحا او عای باندې څه کړي وو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_3.mp3', '', 1761754199, 1761754199),
(48346, 'Joshua 9:4', 'Joshua', 9, 4, 'او هغوی د یوشع د غولولو پرېکړه وکړه. هغوی لاړل او یو څه خواړه یې راواخیستل او په زړو بوجیو او ګنډل شویو د شرابو مشکونه یې په خپلو خرو بار کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_4.mp3', '', 1761754199, 1761754199),
(48347, 'Joshua 9:5', 'Joshua', 9, 5, 'هغو خلکو زړې او ګنډل شوې څپلۍ او زاړه کالي واغوستل. کومه ډوډۍ چې هغوی د ځان سره اخیستې وه هغه وچه او چڼاسکو وهلې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_5.mp3', '', 1761754199, 1761754199),
(48348, 'Joshua 9:6', 'Joshua', 9, 6, 'بیا هغوی یوشع ته هغه کمپ ته ورغلل چې په جلجال کې ؤ او هغه او اسراییلیانو ته یې وویل: «مونږ د یو لېرې هېواد څخه راغلي یو، ستاسو څخه غواړو چې زمونږ سره د سولې تړون وکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_6.mp3', '', 1761754199, 1761754199),
(48349, 'Joshua 9:7', 'Joshua', 9, 7, 'خو اسراییلیانو وویل: «مونږ څنګه پوه شو چې تاسو زمونږ سره نژدې نه اوسېږئ؟ که چېرې نژدې اوسېږئ، نو بیا مونږ نه شو کولای چې ستاسو سره تړون وکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_7.mp3', '', 1761754199, 1761754199),
(48350, 'Joshua 9:8', 'Joshua', 9, 8, 'هغوی یوشع ته وویل: «مونږ ستا غلامان یو.» یوشع پوښتنه وکړه: «تاسو څوک یئ او د کوم ځای څخه راغلي یئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_8.mp3', '', 1761754199, 1761754199),
(48351, 'Joshua 9:9', 'Joshua', 9, 9, 'هغوی په ځواب کې وویل: «ښاغلیه، مونږ د یو ډېر لېرې هېواد څخه راغلي یو، ځکه چې مونږ ستاسو د څښتن خدای د شهرت په اړه اورېدلي دي. مونږ د هغو ټولو کارونو څخه خبر یو چې هغه په مصر کې کړي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_9.mp3', '', 1761754199, 1761754199),
(48352, 'Joshua 9:10', 'Joshua', 9, 10, 'او هرڅه چې هغه د اردن د سیند په ختیځ کې د اموریانو په دوو پاچاهانو باندې وکړل یعنې د حشبون په پاچا سیحون او د باشان په پاچا عوج چې په عشتاروت کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_10.mp3', '', 1761754199, 1761754199),
(48353, 'Joshua 9:11', 'Joshua', 9, 11, 'زمونږ مشرانو او هغو ټولو خلکو چې زمونږ په هېواد کې اوسیږي مونږ ته وویل چې د خپل سفر دپاره له ځان سره د خوړلو او څښلو دپاره یو څه یوسو، لاړ شو د اسراییلیانو سره ووینو او ورته ووایو چې مونږ ستاسو غلامان یو، زمونږ سره یو تړون وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_11.mp3', '', 1761754199, 1761754199),
(48354, 'Joshua 9:12', 'Joshua', 9, 12, 'زمونږ ډوډۍ ته وګورئ. کله چې مونږ د کور څخه راروان شو هغه توده وه. خو اوس وګورئ! هغه وچه شوې او چڼاسکو وهلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_12.mp3', '', 1761754199, 1761754199),
(48355, 'Joshua 9:13', 'Joshua', 9, 13, 'کله چې مونږ د شرابو دا مشکونه ډک کړل، هغه نوي وو. خو وګورئ! هغه شلېدلي دي. د دې اوږد سفر له امله زمونږ کالي او څپلۍ زړې شوې دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_13.mp3', '', 1761754199, 1761754199),
(48356, 'Joshua 9:14', 'Joshua', 9, 14, 'اسراییلیانو د هغوی یو څه ډوډۍ قبوله کړه، خو په دې هکله یې د څښتن سره مشوره ونه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_14.mp3', '', 1761754199, 1761754199),
(48357, 'Joshua 9:15', 'Joshua', 9, 15, 'یوشع د جبعون د خلکو سره د دوستۍ تړون وکړ او هغوی یې ژوندي پرېښودل. د اسراییلو مشرانو قسم وخوړ چې په دې تړون باندې به عمل کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_15.mp3', '', 1761754199, 1761754199),
(48358, 'Joshua 9:16', 'Joshua', 9, 16, 'د جبعونیانو سره د تړون د کولو څخه درې ورځې وروسته اسراییلیانو واورېدل چې دا ګاونډیان دي او د هغوی سره نژدې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_16.mp3', '', 1761754199, 1761754199),
(48359, 'Joshua 9:17', 'Joshua', 9, 17, 'نو اسراییلیان روان شول او په درېمه ورځ هغو ښارونو ته ورسېدل چې دا خلک په کې اوسېدل یعنې جبعون، کفیره، بیروت او قریت یعاریم ته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_17.mp3', '', 1761754199, 1761754199),
(48360, 'Joshua 9:18', 'Joshua', 9, 18, 'خو اسراییلیانو نه شو کولای چې هغوی ووژني، ځکه چې د هغوی مشرانو د جبعونیانو سره د اسراییلو د څښتن خدای په نوم قسم خوړلی ؤ. ټول قوم د مشرانو څخه ګیله وکړه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_18.mp3', '', 1761754199, 1761754199),
(48361, 'Joshua 9:19', 'Joshua', 9, 19, 'خو هغوی په ځواب کې وویل: «مونږ د هغوی سره د اسراییلو د څښتن خدای په نوم قسم خوړلی دی. اوس هغوی ته زیان نه شو رسولی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_19.mp3', '', 1761754199, 1761754199),
(48362, 'Joshua 9:20', 'Joshua', 9, 20, 'مونږ باید د خپلې وعدې په خاطر هغوی ژوندي پرېږدو. که داسې ونه کړو، نو خدای به مونږ ته سزا راکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_20.mp3', '', 1761754199, 1761754199),
(48363, 'Joshua 9:21', 'Joshua', 9, 21, 'هغوی ژوندي پرېږدئ، خو هغوی باید زمونږ دپاره لرګي مات کړي او اوبه راوړي.» دا د مشرانو وړاندیز ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_21.mp3', '', 1761754199, 1761754199),
(48364, 'Joshua 9:22', 'Joshua', 9, 22, 'بیا یوشع د جبعون خلک راوغوښتل او هغوی ته یې وویل: «تاسو ولې مونږ وغولولو او داسې مو وویل چې مونږ د لېرې ځای څخه یو، حال دا چې زمونږ سره نژدې اوسېږئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_22.mp3', '', 1761754199, 1761754199),
(48365, 'Joshua 9:23', 'Joshua', 9, 23, 'په دې خاطر چې تاسو داسې کار وکړ، نو اوس په تاسو باندې لعنت ویل شوی دی. ستاسو خلک به تل ترتله غلامان وي او زما د خدای کور ته به لرګي ماتوي او اوبه به راوړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_23.mp3', '', 1761754199, 1761754199),
(48366, 'Joshua 9:24', 'Joshua', 9, 24, 'هغوی په ځواب کې وویل: «ښاغلیه، مونږ خبر شو چې دا رښتیا وه چې ستا څښتن خدای خپل خدمتګار موسی ته حکم کړی ؤ چې تاته به دا ټوله ځمکه درکړي او کوم خلک چې په کې اوسیږي هغوی به ستا له مخې څخه ورک کړي. نو مونږ ځکه داسې کار وکړ چې ستاسو څخه سخت وېرېدلو چې مونږ به ووژنئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_24.mp3', '', 1761754199, 1761754199),
(48367, 'Joshua 9:25', 'Joshua', 9, 25, 'اوس مونږ ستا په لاس کې یو. هرڅه چې تاته ښه او مناسب ښکاري زمونږ سره یې وکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_25.mp3', '', 1761754199, 1761754199),
(48368, 'Joshua 9:26', 'Joshua', 9, 26, 'نو یوشع هغوی د اسراییلیانو څخه وژغورل او هغوی جبعونیان ونه وژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_26.mp3', '', 1761754199, 1761754199),
(48369, 'Joshua 9:27', 'Joshua', 9, 27, 'خو په هماغه ورځ یوشع هغوی غلامان کړل چې د اسراییلو خلکو او د څښتن د قربانۍ ځای دپاره لرګي مات کړي او اوبه ورته راوړي. تر نن ورځې پورې هغوی په هغه ځای کې چې څښتن د خپل عبادت دپاره غوره کړی دی همدا کار کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua9_verse_27.mp3', '', 1761754199, 1761754199),
(48370, 'Psalms 57:1', 'Psalms', 57, 1, 'په ما رحم وکړه خدایه، رحم وکړه ځکه چې تاته مې پناه راوړې پناه به زه ستا د وزرو تر سیوري لاندې واخلم ترڅو تېر دغه افت شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms57_verse_1.mp3', '', 1761754199, 1761754199),
(48371, 'Psalms 57:2', 'Psalms', 57, 2, 'زه کومه خدای تعالی ته فریاد هغه خدای ته چې خپل مقصد زما دپاره سر ته رسوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms57_verse_2.mp3', '', 1761754199, 1761754199),
(48372, 'Psalms 57:3', 'Psalms', 57, 3, 'کړي له اسمانه به قبوله مې دعا نجات به راکړي ماته هغه چې ما باندې کړي ظلم خدای به ورکړي شرم خدای به راوښایي وفا او هم تلپاتې مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms57_verse_3.mp3', '', 1761754199, 1761754199),
(48373, 'Psalms 57:4', 'Psalms', 57, 4, 'زه د داسې دښمنانو له خوا ګېر یم چې د زمرو په شان دي وږي د انسان غوښو ته د دوی غاښونه دي د غشو او نېزو په شان د هغوی ژبې دي تېرې لکه د تورو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms57_verse_4.mp3', '', 1761754199, 1761754199),
(48374, 'Psalms 57:5', 'Psalms', 57, 5, 'خدایه لویي دې کړه ظاهره اسمانونو باندې په ټوله ځمکه خپل جلال ښکاره کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms57_verse_5.mp3', '', 1761754199, 1761754199),
(48375, 'Psalms 57:6', 'Psalms', 57, 6, 'دی دښمنانو راته ایښی دام چې ګېر مې کړي له پرېشانۍ نه ستړی شوی یمه کنده کیندلې وه هغوی راته په لاره کې خو دوی په خپله په کې ولوېدل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms57_verse_6.mp3', '', 1761754199, 1761754199),
(48376, 'Psalms 57:7', 'Psalms', 57, 7, 'زه په تا باندې ډاډه یمه ای خدایه زه ډاډه یم زه به وایمه سندرې ستا صفت به کوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms57_verse_7.mp3', '', 1761754199, 1761754199),
