(48380, 'Psalms 57:11', 'Psalms', 57, 11, 'خدایه لویي دې کړه ظاهره اسمانونو باندې په ټوله ځمکه خپل جلال ښکاره کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms57_verse_11.mp3', '', 1761754199, 1761754199),
(48381, 'Leviticus 1:1', 'Leviticus', 1, 1, 'څښتن موسی د سپېڅلې خېمې څخه راوغوښت او ورته ویې ویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_1.mp3', '', 1761754199, 1761754199),
(48382, 'Leviticus 1:2', 'Leviticus', 1, 2, '«اسراییلیانو ته ووایه: کله چې ستاسو څخه یو څوک څښتن ته یوه نذرانه راوړي، نو هغه دې د خپلې پادې یا رمې څخه یو حیوان د خپلې نذرانې په توګه راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_2.mp3', '', 1761754199, 1761754199),
(48383, 'Leviticus 1:3', 'Leviticus', 1, 3, 'که چېرې هغه د خپلې پادې څخه یو حیوان د سوځېدونکې نذرانې په توګه وړاندې کوي، هغه باید یو داسې خوسی راولي چې څه عیب په کې نه وي. هغه باید د سپېڅلې خېمې د دروازې په خوله کې وړاندې کړي، ترڅو څښتن هغه قبول کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_3.mp3', '', 1761754199, 1761754199),
(48384, 'Leviticus 1:4', 'Leviticus', 1, 4, 'هغه به د حیوان په سر باندې خپل لاس کېږدي او دا به د هغه د ګناهونو د لېرې کولو دپاره د کفارې په توګه قبول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_4.mp3', '', 1761754199, 1761754199),
(48385, 'Leviticus 1:5', 'Leviticus', 1, 5, 'هغه باید د څښتن په حضور کې خوسی حلال کړي او د هارون زامن به چې د کاهنانو په توګه خدمت کوي، د هغه وینه راوړي او د قربانۍ د ځای په څلورو خواو باندې چې د سپېڅلې خېمې د دروازې په مخکې ده، وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_5.mp3', '', 1761754199, 1761754199),
(48386, 'Leviticus 1:6', 'Leviticus', 1, 6, 'بیا دې د هغه حیوان پوستکی وباسي او ټوټې ټوټې به یې کړي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_6.mp3', '', 1761754199, 1761754199),
(48387, 'Leviticus 1:7', 'Leviticus', 1, 7, 'او کاهنان دې د قربانۍ په ځای باندې لرګي په ترتیب سره کېږدي او اور دې بل کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_7.mp3', '', 1761754199, 1761754199),
(48388, 'Leviticus 1:8', 'Leviticus', 1, 8, 'هغوی دې د حیوان ټوټې شوې برخې د سر او وازګې سره په اور باندې کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_8.mp3', '', 1761754199, 1761754199),
(48389, 'Leviticus 1:9', 'Leviticus', 1, 9, 'بیا دې هغه کس کولمې او پښې ووینځي او کاهن دې هغه ټول د قربانۍ په ځای باندې وسوځوي. دا سوځېدونکې نذرانه ده، یو داسې بوی دی چې په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_9.mp3', '', 1761754199, 1761754199),
(48390, 'Leviticus 1:10', 'Leviticus', 1, 10, 'که چېرې هغه کس د خپلې رمې څخه یو حیوان وړاندې کوي، هغه باید نر وي او څه عیب په کې نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_10.mp3', '', 1761754199, 1761754199),
(48391, 'Leviticus 1:11', 'Leviticus', 1, 11, 'هغه باید د څښتن په حضور کې د قربانۍ د ځای شمال خواته حلال کړي او کاهنان به د هغه وینه د قربانۍ د ځای په څلورو خواو باندې وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_11.mp3', '', 1761754199, 1761754199),
(48392, 'Leviticus 1:12', 'Leviticus', 1, 12, 'وروسته له دې چې حیوان ټوټې ټوټې شي، کاهن به دا ټولې برخې د سر او وازګې سره په اور باندې کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_12.mp3', '', 1761754199, 1761754199),
(48393, 'Leviticus 1:13', 'Leviticus', 1, 13, 'هغه باید کولمې او پښې ووینځي او کاهن دې دا قرباني وړاندې کړي او هغه ټول دې د قربانۍ په ځای باندې وسوځوي. دا سوځېدونکې نذرانه ده، یو داسې بوی چې په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_13.mp3', '', 1761754199, 1761754199),
(48394, 'Leviticus 1:14', 'Leviticus', 1, 14, 'که چېرې څوک یوه مرغۍ د سوځېدونکې نذرانې په توګه وړاندې کوي، هغه باید یوه کوتره یا قمري وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_14.mp3', '', 1761754199, 1761754199),
(48395, 'Leviticus 1:15', 'Leviticus', 1, 15, 'کاهن دې هغه د قربانۍ په ځای باندې وړاندې کړي، د هغې ورمېږ دې تاو کړي او سر یې د قربانۍ په ځای باندې وسوځوي. د هغې وینه دې د قربانۍ د ځای په اړخ کې وڅڅیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_15.mp3', '', 1761754199, 1761754199),
(48396, 'Leviticus 1:16', 'Leviticus', 1, 16, 'د هغې ججوره دې د هرڅه سره لېرې کړي او د قربانۍ د ځای لمرخاته خواته دې چې ایرې اچول کیږي، وغورځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_16.mp3', '', 1761754199, 1761754199),
(48397, 'Leviticus 1:17', 'Leviticus', 1, 17, 'د هغې وزرونه دې ونیسي او د هغې بدن دې په منځ کې داسې څیرې کړي چې وزرونه یې ورڅخه بېل نه شي او بیا دې هغه ټول د قربانۍ په ځای باندې وسوځوي. دا سوځېدونکې نذرانه ده، یو داسې بوی چې په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus1_verse_17.mp3', '', 1761754199, 1761754199),
(48398, 'Deuteronomy 20:1', 'Deuteronomy', 20, 1, 'کله چې تاسو د خپلو دښمنانو سره د جګړې دپاره لاړ شئ او ووینئ چې د هغوی جنګي ګاډۍ او اسونه او لښکر ستاسو نه زیات وي، د هغوی څخه مه وېرېږئ. ستاسو څښتن خدای چې تاسو یې د مصر څخه ازاد کړئ هغه به ستاسو سره مل وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_1.mp3', '', 1761754199, 1761754199),
(48399, 'Deuteronomy 20:2', 'Deuteronomy', 20, 2, 'مخکې له دې چې تاسو جګړه پیل کړئ، یو کاهن دې مخکې راشي او لښکر ته دې داسې ووایي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_2.mp3', '', 1761754199, 1761754199),
(48400, 'Deuteronomy 20:3', 'Deuteronomy', 20, 3, '‹د اسراییلو خلکو، واورئ! تاسو نن جګړې ته روان یئ. د خپلو دښمنانو څخه ونه وېرېږئ او جرات د لاسه ورنه کړئ او وارخطا نه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_3.mp3', '', 1761754199, 1761754199),
(48401, 'Deuteronomy 20:4', 'Deuteronomy', 20, 4, 'ځکه چې ستاسو سره خپل څښتن خدای روان دی چې ستاسو په خاطر ستاسو د دښمنانو په وړاندې وجنګیږي او تاسو ته بری درکړي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_4.mp3', '', 1761754199, 1761754199),
(48402, 'Deuteronomy 20:5', 'Deuteronomy', 20, 5, 'بیا دې منصبداران لښکرو ته وینا وکړي او ودې وایي: ‹ایا دلته داسې سړی شته چې نوی کور یې ودان کړی وي، خو لا تر اوسه پورې یې ورته کډه نه وي وروړې؟ که چېرې وي، نو هغه دې کور ته لاړ شي. که نه، نو که چېرې هغه په جګړه کې ووژل شي، بل څوک به د هغه په کور کې واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_5.mp3', '', 1761754199, 1761754199),
(48403, 'Deuteronomy 20:6', 'Deuteronomy', 20, 6, 'ایا دلته داسې سړی شته چې د انګورو باغ یې جوړ کړی وي، خو لا تر اوسه یې دا موقع نه وي موندلې چې د هغه څخه انګور راټول کړي؟ که چېرې وي، نو هغه دې کور ته لاړ شي. که نه، نو که چېرې هغه په جګړه کې ووژل شي، بل څوک به یې د مېوو څخه خوند واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_6.mp3', '', 1761754199, 1761754199),
(48404, 'Deuteronomy 20:7', 'Deuteronomy', 20, 7, 'ایا دلته داسې څوک شته چې کوژدن یې کړې وي او تر اوسه پورې یې واده نه وي کړی؟ که چېرې وي، نو هغه دې کور ته لاړ شي. که نه، نو که چېرې هغه په جګړه کې ووژل شي او بل څوک به د هغه د کوژدن شوې ښځې سره واده وکړي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_7.mp3', '', 1761754199, 1761754199),
(48405, 'Deuteronomy 20:8', 'Deuteronomy', 20, 8, 'منصبداران به لښکرو ته دا هم ووایي: ‹ایا دلته داسې سړی شته چې خپل جرات یې له لاسه ورکړی وي او وېریږي؟ که چېرې وي، نو هغه دې کور ته لاړ شي. که نه، نو هغه به د نورو روحیه کمزورې کړي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_8.mp3', '', 1761754199, 1761754199),
(48406, 'Deuteronomy 20:9', 'Deuteronomy', 20, 9, 'کله چې منصبداران د لښکرو سره خپلې خبرې خلاصې کړي، نو قوماندانان دې د لښکرو مشري په غاړه واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_9.mp3', '', 1761754199, 1761754199),
(48407, 'Deuteronomy 20:10', 'Deuteronomy', 20, 10, 'کله چې تاسو په یو ښار باندې د حملې دپاره لاړ شئ، لومړی د هغه ځای خلکو ته د تسلیمېدلو موقع ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_10.mp3', '', 1761754199, 1761754199),
(48408, 'Deuteronomy 20:11', 'Deuteronomy', 20, 11, 'که چېرې هغوی دروازې خلاصې کړي او تسلیم شي، هغوی ټول دې ستاسو غلامان شي او ستاسو دپاره دې سخت کارونه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_11.mp3', '', 1761754199, 1761754199),
(48409, 'Deuteronomy 20:12', 'Deuteronomy', 20, 12, 'خو که چېرې د هغه ښار خلک تسلیم نه شي بلکې وجنګیږي، د خپلو لښکرو په وسیله هغه ښار کلابند کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_12.mp3', '', 1761754199, 1761754199),
(48410, 'Deuteronomy 20:13', 'Deuteronomy', 20, 13, 'کله چې څښتن ستاسو خدای هغه ښار تاسو ته په لاس درکړي، بیا د هغه ټول سړي ووژنئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy20_verse_13.mp3', '', 1761754199, 1761754199);